package com.example.kyrgyzkeyboard.utils

import android.content.Context
import android.media.AudioManager
import android.os.Build
import android.os.VibrationEffect
import android.os.Vibrator
import android.os.VibratorManager
import androidx.core.content.getSystemService
import kotlin.math.max
import kotlin.math.min

/**
 * 键盘辅助工具。除震动与按键音需要 [Context] 外，其余为纯几何计算。
 */
object KeyboardHelper {

    /** 短促震动反馈：15ms 单发，兼容 API 24+。 */
    fun vibrate(context: Context, durationMs: Long = 15L) {
        val vibrator = obtainVibrator(context) ?: return
        if (!vibrator.hasVibrator()) return
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            vibrator.vibrate(
                VibrationEffect.createOneShot(durationMs, VibrationEffect.DEFAULT_AMPLITUDE)
            )
        } else {
            @Suppress("DEPRECATION")
            vibrator.vibrate(durationMs)
        }
    }

    /** 播放系统按键音（跟随系统「按键操作音」总开关）。 */
    fun playKeySound(context: Context) {
        val am = context.getSystemService<AudioManager>() ?: return
        am.playSoundEffect(AudioManager.FX_KEYPRESS_STANDARD, 1f)
    }

    /**
     * 键盘的可用宽度：默认占满屏宽；若后续做浮动小键盘可调用者传入自定比例。
     */
    fun getKeyboardWidth(screenWidth: Int): Int = max(0, screenWidth)

    /**
     * 按行内键数均分计算单键像素宽度，向下取整以避免最后一列溢出。
     * 若 [keysPerRow] <= 0，返回 0。
     */
    fun calculateKeySize(screenWidth: Int, keysPerRow: Int): Int {
        if (keysPerRow <= 0) return 0
        val usable = getKeyboardWidth(screenWidth)
        return min(usable, usable / keysPerRow)
    }

    private fun obtainVibrator(context: Context): Vibrator? {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            context.getSystemService<VibratorManager>()?.defaultVibrator
        } else {
            @Suppress("DEPRECATION")
            context.getSystemService<Vibrator>()
        }
    }
}